/* O painel é Laravel: o POST de login só é aceito com o _token (CSRF) que a
   própria tela de login entrega, junto do cookie de sessão daquela visita.
   Por isso o login tem dois passos — abrir a tela, depois enviar. */
const r = $input.first().json;
const corpo = String(r.body || r.data || '');
const m = corpo.match(/name="csrf-token"\s+content="([^"]+)"/)
       || corpo.match(/name="_token"\s+value="([^"]+)"/);
if (!m) throw new Error('Não achei o _token na tela de login — o painel pode ter mudado');

const bruto = (r.headers || {})['set-cookie'] || [];
const cookie = (Array.isArray(bruto) ? bruto : [bruto])
  .map(c => String(c).split(';')[0]).join('; ');

return [{ json: { csrf: m[1], cookie } }];

/* Guarda o cookie da sessão já autenticada, para os nós do painel
   reaproveitarem. Sem captcha no login, isso se renova a cada rodada — ninguém
   precisa colar cookie à mão quando expirar. */
const r = $input.first().json;
const bruto = (r.headers || {})['set-cookie'] || [];
const novos = (Array.isArray(bruto) ? bruto : [bruto])
  .map(c => String(c).split(';')[0]);
const anterior = $('Extrai o _token').first().json.cookie || '';

// O cookie da sessão logada substitui o da visita anônima quando repetido
const mapa = {};
(anterior.split('; ').concat(novos)).forEach(c => {
  const i = c.indexOf('=');
  if (i > 0) mapa[c.slice(0, i)] = c.slice(i + 1);
});
const cookie = Object.entries(mapa).map(([k, v]) => k + '=' + v).join('; ');

/* Login recusado tem que parar AQUI, alto. O Laravel responde 200 com a
   própria tela de login quando a senha está errada — nada explode, o cookie
   até existe, e a falha só reaparece três nós adiante como "401 não
   autenticado" ou, pior, como "detalhe vazio", que parece problema do envio.
   Login aceito redireciona (302 + Location). */
const status = Number(r.statusCode || r.status || 0);
const cabecalhos = r.headers || {};
const local = cabecalhos.location || cabecalhos.Location || '';
const corpo = String(r.body || '');
const telaDeLogin = /css\/login\/|name="password"|id="password"|esqueci\s*minha\s*senha/i.test(corpo);

if (!local && status < 300 && telaDeLogin) {
  throw new Error('Login do Manda Bem recusado: o painel devolveu a tela de login de novo. ' +
                  'Confira a senha no campo "password" do nó "Login Manda Bem" — no arquivo do ' +
                  'repositório ela vai como PREENCHER_A_SENHA_AQUI, porque o repositório é público.');
}
return [{ json: { cookie } }];

// Entrada: o objeto inteiro de rastreios. Saída: só o que vale consultar agora.
const todos = $input.first().json || {};
const agora = Date.now();
const DIAS_ATE_DESISTIR = 45;
const FONTES = ['Melhor Envio', 'Manda Bem'];
let semFonte = 0;

const fila = Object.entries(todos).map(([chave, r]) => ({ chave, ...r })).filter(r => {
  if (!r || !r.codigo) return false;                    // sem código não há o que consultar
  if (r.status === 'Entregue') return false;            // trabalho encerrado
  if (r.trackProximaConsulta && agora < r.trackProximaConsulta) return false; // backoff

  // Pacote parado há mais de 45 dias não volta a andar porque perguntamos de
  // novo. Sai da fila e vira problema humano, não de robô.
  const nasceu = Number(r.ordemManual || 0);
  if (nasceu && (agora - nasceu) > DIAS_ATE_DESISTIR * 864e5) return false;

  /* Sem intermediador não há onde perguntar. Deixar passar não era inofensivo:
     o item caía na saída "Sem fonte" do Switch e chegava ao normalizador como
     card cru, que lia o campo "status" do próprio card e o gravava de volta
     como se fosse resposta da transportadora — o rastreio parecia atualizado
     de hora em hora sem nunca ter consultado nada. */
  if (FONTES.indexOf(String(r.intermediador || '').trim()) < 0) { semFonte++; return false; }

  return true;
});

if (semFonte) {
  console.log(semFonte + ' rastreio(s) fora da fila por não ter intermediador definido no card');
}

/* O id que o painel do Manda Bem entende é numérico, e ele já está dentro do
   próprio código de rastreio: "MB0000000328080" carrega o 328080, o mesmo
   número que aparece no data-path do botão de rastreio. Deduzir aqui evita
   depender de alguém digitar certo — e o campo do card, quando preenchido com
   número, continua mandando. Não-numérico ali (já colaram a chave do card,
   "rst_1786…") é ignorado de propósito: id errado consulta o envio de outra
   pessoa, o que é pior que não consultar. */
function idDoMandaBem(r) {
  const doCard = String(r.envioId || r.coletaId || '').trim();
  if (/^\d+$/.test(doCard)) return doCard;
  const doCodigo = String(r.codigo || '').replace(/\D/g, '').replace(/^0+/, '');
  return doCodigo || '';
}

return fila.map(r => ({
  json: r.intermediador === 'Manda Bem' ? { ...r, mbId: idDoMandaBem(r) } : r
}));

/* O HTML do detalhe traz o botão da lupa com o endereço do rastreio pronto.
   Ler daqui vale mais que qualquer tabela de slugs: funciona para
   transportadora que ainda nem existe no cadastro.

   Três cuidados aprendidos na marra:
   · o data-path costuma vir RELATIVO ("coleta/status_jadlog_objeto/328080").
     Mandar isso para o nó HTTP dá ERR_INVALID_URL, que na tela vira um erro
     sem sentido para quem só queria saber onde está a encomenda;
   · nem todo envio tem o botão — sem objeto postado, ele não existe. Isso não
     é falha do fluxo, é estado do pacote, e precisa dizer isso;
   · o HTML vem com barras escapadas (\/) por causa do JSON. */
const BASE = 'https://painel.mandabem.com.br/';
const html = $json.html || $json.data || '';

let achado = '';
const padroes = [
  /class="[^"]*btn-get-status-objeto-envio[^"]*"[^>]*data-path="([^"]+)"/i,
  /data-path="([^"]*status[^"]*objeto[^"]*)"/i,
  /data-path="([^"]*(?:rastre|track)[^"]*)"/i,
  /(?:href|data-url)="([^"]*status[^"]*objeto[^"]*)"/i
];
for (const re of padroes) {
  const m = String(html).match(re);
  if (m && m[1]) { achado = m[1]; break; }
}

let url = achado.replace(/\\\//g, '/').trim();
if (url && !/^https?:\/\//i.test(url)) url = BASE + url.replace(/^\/+/, '');

// Sem link, o motivo vai junto: é ele que o card vai mostrar
const motivo = url ? ''
  : (String(html).trim()
      ? 'O Manda Bem não mostrou botão de rastreio neste envio — normalmente é objeto ainda não postado'
      : 'O Manda Bem devolveu o detalhe vazio para este envio');

return { json: { ...$json, trackUrl: url, trackUrlMotivo: motivo } };

/**
 * Padroniza a resposta de qualquer fonte de rastreio.
 *
 * Saída (uma por item):
 *   status_atual          — o último status, em texto
 *   historico_movimentacoes — [{data, status, local, detalhe}], mais novo primeiro
 *   data_hora_consulta    — quando perguntamos
 *
 * A leitura de cada formato é defensiva de propósito: transportadora muda
 * nome de campo sem avisar, e é melhor gravar um histórico incompleto do que
 * derrubar a rodada com "cannot read property of undefined".
 */

const TZ = 'America/Sao_Paulo';

const agora = new Date();
const carimbo = agora.toLocaleString('pt-BR', {
  timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

/* "2026-08-17T14:07:00Z" | "17/08/2026 14:07" | Date → "17/08/2026, 14:07"
   O formato de saída é sempre o mesmo, com vírgula. Isso não é capricho: a
   comparação "mudou desde a última consulta?" é feita sobre esse texto, e
   "17/08/2026 08:00" contra "17/08/2026, 08:00" seria lido como movimentação
   nova a cada hora — o card seria reescrito para sempre, sem nada ter
   acontecido. */
function paraDataBR(valor) {
  if (!valor) return '';
  const br = String(valor).match(/^(\d{2})\/(\d{2})\/(\d{4})[,\s]*(\d{2}):(\d{2})?/);
  if (br) return `${br[1]}/${br[2]}/${br[3]}, ${br[4]}:${br[5] || '00'}`;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(String(valor).trim())) return String(valor).trim();
  const d = new Date(valor);
  if (isNaN(d.getTime())) return String(valor);
  return d.toLocaleString('pt-BR', {
    timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
}

function primeiro(obj, ...campos) {
  for (const c of campos) {
    const v = c.split('.').reduce((o, k) => (o == null ? o : o[k]), obj);
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}

// ── Um evento, venha de onde vier ────────────────────────────
function normalizarEvento(e) {
  return {
    data:    paraDataBR(primeiro(e, 'created_at', 'date', 'dtHrCriado', 'data', 'occurredAt', 'time_iso', 'datetime')),
    status:  primeiro(e, 'status', 'descricao', 'description', 'situacao', 'title', 'event', 'message'),
    local:   primeiro(e, 'location', 'local', 'city', 'unidade.endereco.cidade', 'cidade', 'origem'),
    detalhe: primeiro(e, 'detail', 'detalhe', 'comment', 'observacao', 'sub_status')
  };
}

// ── Cada fonte devolve os eventos num lugar diferente ────────
function eventosDaFonte(fonte, resposta) {
  if (!resposta) return [];
  switch (fonte) {
    case 'melhor-envio': {
      // { "<id>": { tracking, status, events: [...] } }
      const primeiroPedido = Object.values(resposta)[0] || {};
      return primeiroPedido.events || primeiroPedido.tracking_events || [];
    }
    case 'manda-bem':
      return resposta.eventos || resposta.events || resposta.tracking || [];
    case 'correios': {
      const obj = (resposta.objetos && resposta.objetos[0]) || {};
      return obj.eventos || [];
    }
    case 'jadlog': {
      const doc = (resposta.consulta && resposta.consulta[0] && resposta.consulta[0].tracking) || {};
      return doc.eventos || [];
    }
    case '17track': {
      const aceito = resposta.data && resposta.data.accepted && resposta.data.accepted[0];
      return (aceito && aceito.track && aceito.track.z1) || [];
    }

    // Painel do Manda Bem: {title, html} — as movimentações estão no HTML
    case 'manda-bem-painel':
      return eventosDoPainelMandaBem(resposta.html || resposta);

    /* Portais (rota B da seção 6). O JSON interno de cada um tem nome próprio
       para a lista de eventos, e ninguém garante que continue o mesmo no mês
       que vem — por isso a busca é por vários nomes, e não por um caminho
       fixo. Se todos falharem, o último recurso varre o objeto atrás de
       qualquer lista que pareça uma linha do tempo. */
    case 'portal-correios':
    case 'portal-loggi':
    case 'portal-melhorrastreio': {
      const candidatos = [
        resposta.eventos, resposta.events, resposta.tracking, resposta.trackings,
        resposta.historico, resposta.history, resposta.movimentacoes, resposta.checkpoints,
        resposta.data && resposta.data.eventos,
        resposta.data && resposta.data.events,
        resposta.data && resposta.data.tracking,
        resposta.result && resposta.result.eventos,
        resposta.objeto && resposta.objeto.eventos,
        // Nó HTML do n8n: as linhas já vêm quebradas em texto
        resposta.linhas
      ];
      for (const c of candidatos) if (Array.isArray(c) && c.length) return c;
      return acharListaDeEventos(resposta);
    }

    default:
      return acharListaDeEventos(resposta);
  }
}

/* Manda Bem devolve HTML dentro de JSON: {title, html}. Cada movimentação
   começa com "Em DD/MM/AAAA HH:MM:SS", seguida da descrição, e há uma coluna
   "Local". A leitura é por essa marca de data, não por seletor de tabela —
   o painel mexe no layout com frequência, mas a data é o que dá sentido ao
   evento e não vai mudar de formato sem quebrar a tela deles também. */
function textoSemTags(t) {
  return String(t || '')
    .replace(/<[^>]*>/g, '\n')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
    .split('\n').map(s => s.replace(/\s+/g, ' ').trim()).filter(Boolean);
}

function eventosDoPainelMandaBem(html) {
  const texto = String(html || '');
  const marca = /Em\s+(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2})(?::\d{2})?/g;
  const marcos = [];
  let m;
  while ((m = marca.exec(texto)) !== null) {
    marcos.push({ inicio: m.index, fim: marca.lastIndex, data: m[1] + ', ' + m[2] });
  }
  return marcos.map((mk, i) => {
    const trecho = texto.slice(mk.fim, i + 1 < marcos.length ? marcos[i + 1].inicio : texto.length);
    const linhas = textoSemTags(trecho);
    const iLocal = linhas.findIndex(l => /^local:?$/i.test(l));
    // A primeira linha que não é o rótulo "Local" é a descrição do evento
    const status = linhas.find((l, k) => k !== iLocal && !/^local:?$/i.test(l)) || '';
    const local = iLocal >= 0 ? (linhas[iLocal + 1] || '') : '';
    return { data: mk.data, status, local, detalhe: '' };
  }).filter(e => e.status);
}

/* Último recurso: vasculha o objeto inteiro atrás da lista que mais parece
   uma linha do tempo — a que tem mais itens com cara de data. Serve para
   quando o portal troca o nome do campo sem avisar: em vez de devolver zero
   evento e o card congelar, ainda se acerta o histórico. */
function acharListaDeEventos(raiz) {
  let melhor = [], nota = 0;
  const parecemData = /^\d{4}-\d{2}-\d{2}|^\d{2}\/\d{2}\/\d{4}/;

  (function varrer(o, nivel) {
    if (!o || typeof o !== 'object' || nivel > 6) return;
    if (Array.isArray(o)) {
      if (o.length && typeof o[0] === 'object') {
        const pontos = o.filter(e => e && Object.values(e).some(
          v => typeof v === 'string' && parecemData.test(v))).length;
        if (pontos > nota) { nota = pontos; melhor = o; }
      }
      o.forEach(v => varrer(v, nivel + 1));
      return;
    }
    Object.values(o).forEach(v => varrer(v, nivel + 1));
  })(raiz, 0);

  return melhor;
}

// ── "Entregue" escrito de todo jeito ─────────────────────────
const PALAVRAS_ENTREGUE = /(entregue|delivered|entrega\s+realizada|objeto\s+entregue)/i;
const PALAVRAS_PROBLEMA = /(extravi|roubo|avaria|devolu|recusad|endere[çc]o\s+(insuficiente|incorreto|errado))/i;

/* Este nó roda UMA VEZ POR ITEM. O card não vem no item: o nó HTTP anterior
   substituiu o conteúdo pela resposta da API. Quem guarda o registro original
   é o nó de lotes, e o n8n sabe casar cada resposta com a entrada que a
   originou — é daí que o card é lido. */
{
  const card  = $('Lotes de 10').item.json;
  const item  = { json: $json };
  // A fonte se reconhece pela cara da resposta: o painel do Manda Bem devolve
  // {title, html}; o Melhor Envio, um objeto por pedido
  const fonte = ($json && $json.html !== undefined) ? 'manda-bem-painel' : 'melhor-envio';
  const bruto = ($json && $json.error) ? null : $json;

  /* Chegou o card, não a resposta de ninguém: é a saída "Sem fonte" do Switch,
     ou um ramo que não consultou. Aqui NÃO se escreve status: o card tem um
     campo "status" próprio (o da equipe: Postado, Em trânsito…) e gravá-lo de
     volta como se fosse da transportadora inventaria um rastreio que nunca
     aconteceu. Só registra o motivo, para a tela poder mostrar. */
  if (bruto && bruto.codigo && bruto.chave) {
    const aviso = 'Sem intermediador definido no card — escolha Melhor Envio ou Manda Bem';
    return { json: {
      chave: bruto.chave,
      mudou: card.trackErro !== aviso,
      patch: { trackErro: aviso, trackConsultadoEm: carimbo, _by: 'n8n' }
    }};
  }

  /* A mensagem de erro do n8n às vezes vem como objeto ({message, description}).
     String(objeto) daria "[object Object]" e o card mostraria isso ao operador,
     escondendo justamente o que a gente precisa ler para consertar. */
  function textoDoErro(e) {
    if (!e) return '';
    var t = (typeof e === 'string') ? e : (e.message || e.description || e.reason || JSON.stringify(e));
    /* 422 "orders.0 deve ter pelo menos 36 caracteres" quer dizer que mandamos
       o id do pedido vazio — ou seja, a busca pelo código não achou o envio no
       Melhor Envio. O texto original fala de um campo de API que o atendente
       nunca viu; o que ele precisa saber é que o código do card não bate com
       nenhum pedido de lá. */
    if (/orders\.0/.test(t) || /36 caracteres/.test(t)) {
      return 'Não achei este envio no Melhor Envio pelo código "' + (card.codigo || '') +
             '" — confira o código ou preencha "Id no intermediador" no card';
    }

    /* "ERR_INVALID_URL input:''" é o que sai quando o passo anterior não achou
       o endereço do rastreio. Do jeito que vem, é um erro de programador na
       tela de quem só quer saber onde está a encomenda — então troca pelo
       motivo de verdade, que o extrator já apurou. */
    if (/ERR_INVALID_URL/.test(t)) {
      /* Antes de repassar o motivo técnico, o caso mais comum e o único que
         alguém pode resolver: o card não tem o id da coleta. A URL do painel
         é get_envios_row/<id>; sem id ela vira um endereço sem fim, o painel
         devolve vazio, e o erro parece do Manda Bem quando é campo em branco
         no nosso lado. */
      if (!card.mbId && !card.envioId && !card.coletaId) {
        return 'Preencha "Id no intermediador" no card — no Manda Bem é o número da coleta';
      }
      try {
        var motivo = $('Extrai o data-path').item.json.trackUrlMotivo;
        if (motivo) return motivo;
      } catch (err) { /* outro ramo: segue com o texto original */ }
      return 'Não foi possível montar o endereço de consulta deste envio';
    }
    return t;
  }

  // Ramo de erro: o HTTP Request falhou (Continue On Fail preserva o item)
  if (item.json.error || !bruto) {
    const falhas = Number(card.trackFalhas || 0) + 1;
    const espera = [1, 3, 6, 12, 24][Math.min(falhas, 5) - 1] * 3600e3;
    return { json: {
      chave: card.chave || card.id,
      mudou: true,
      patch: {
        trackErro: (textoDoErro(item.json.error) || 'sem resposta da API').slice(0, 300),
        trackFalhas: falhas,
        trackConsultadoEm: carimbo,
        trackProximaConsulta: Date.now() + espera,
        _by: 'n8n'
      }
    }};
  }

  const eventos = eventosDaFonte(fonte, bruto)
    .map(normalizarEvento)
    .filter(e => e.status || e.data);

  // Mais novo primeiro — é a ordem que o card mostra
  eventos.sort((a, b) => {
    const t = s => {
      const m = String(s).match(/^(\d{2})\/(\d{2})\/(\d{4}),?\s*(\d{2}):(\d{2})/);
      return m ? new Date(+m[3], +m[2] - 1, +m[1], +m[4], +m[5]).getTime() : 0;
    };
    return t(b.data) - t(a.data);
  });

  /* Sem evento datado, ainda pode haver recado: o painel do Manda Bem
     responde "Objeto aguardando postagem." como texto solto, sem data. Jogar
     isso fora e escrever "Sem movimentação" seria apagar a única informação
     que veio. */
  const recado = bruto && bruto.html ? (textoSemTags(bruto.html)[0] || '') : '';

  /* Sem evento datado ainda há informação: o Melhor Envio devolve o estado do
     pedido ({ "<id>": { status: "posted", ... } }), e "Sem movimentação" no
     card seria jogar isso fora. O objeto do pedido está um nível abaixo — ler
     "status" na raiz não acha nada. */
  const objeto = (fonte === 'melhor-envio' && bruto) ? (Object.values(bruto)[0] || {}) : (bruto || {});
  const ESTADOS = {
    pending: 'Aguardando pagamento', paid: 'Pago, aguardando etiqueta',
    generated: 'Etiqueta gerada', released: 'Etiqueta liberada',
    posted: 'Postado', delivered: 'Entregue', canceled: 'Cancelado',
    undelivered: 'Não entregue', returned: 'Devolvido', expired: 'Etiqueta expirada'
  };
  const cru = primeiro(objeto, 'status', 'situacao', 'current_status', 'tracking_status');
  const status_atual = eventos.length
    ? eventos[0].status
    : ((ESTADOS[String(cru).toLowerCase()] || cru) || recado || 'Sem movimentação');

  const padrao = {
    status_atual,
    historico_movimentacoes: eventos,
    data_hora_consulta: carimbo
  };

  // Mudou desde a última consulta? Compara pelo conteúdo, não pelo horário —
  // senão toda rodada pareceria uma novidade e reescreveria o card à toa.
  const antes = JSON.stringify((card.trackHistorico || []).map(e => e.data + e.status));
  const depois = JSON.stringify(eventos.map(e => e.data + e.status));
  const mudou = antes !== depois || card.trackStatus !== status_atual;

  const patch = {
    trackStatus: padrao.status_atual,
    trackHistorico: padrao.historico_movimentacoes,
    trackConsultadoEm: padrao.data_hora_consulta,
    trackFonte: fonte,
    trackErro: '',
    trackFalhas: 0,
    trackProximaConsulta: 0,
    _by: 'n8n'
  };

  // Entrega confirmada é o único caso em que o robô mexe no status da equipe:
  // é o que tira o card da lista ativa, como se alguém tivesse marcado.
  if (PALAVRAS_ENTREGUE.test(status_atual)) {
    patch.status = 'Entregue';
    patch.entregueEm = eventos[0] ? eventos[0].data : carimbo;
  } else if (PALAVRAS_PROBLEMA.test(status_atual)) {
    // Problema NÃO vira status automático: quem decide entre "Extraviado",
    // "Voltando" e "Endereço errado" é quem fala com o cliente. O robô só
    // sinaliza para o card acender.
    patch.trackAlerta = status_atual;
  }

  /* O id do pedido no Melhor Envio é caro de descobrir (uma busca a mais).
     Achado uma vez, é gravado no card — nas próximas rodadas vai direto. */
  if (!card.envioId) {
    try {
      const achado = $('Id do pedido').item.json.envioId;
      if (achado) patch.envioId = achado;
    } catch (e) { /* rodada do Manda Bem: este nó não existe no caminho */ }
  }

  return { json: { chave: card.chave || card.id, mudou, patch, padrao } };
}

/* O Melhor Envio consulta o rastreio pelo id do pedido DELE, e o card só tem
   o código da transportadora. Pegar esse id à mão, envio a envio, é trabalho
   que ninguém vai fazer todo dia — então ele é descoberto aqui, casando pelo
   código, e depois gravado no card para não precisar buscar de novo. */
const card = $('Lotes de 10').item.json;
const alvo = String(card.codigo || '').replace(/\s/g, '').toUpperCase();

let achado = '';
(function varrer(o) {
  if (!o || typeof o !== 'object' || achado) return;
  if (Array.isArray(o)) { o.forEach(varrer); return; }
  const codigos = [o.tracking, o.self_tracking, o.protocol, o.code]
    .filter(Boolean).map(x => String(x).toUpperCase());
  if (o.id && codigos.includes(alvo)) { achado = o.id; return; }
  Object.values(o).forEach(varrer);
})($json);

// Sem id não há consulta possível: segue com o campo vazio e o ramo de erro
// registra a pendência no card, em vez de a rodada morrer aqui
return { json: { ...card, envioId: achado } };
